export function parseEuro(value){let s=String(value||'').replace(/[^0-9,.-]/g,'');if(s.includes(','))s=s.replaceAll('.','').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replaceAll('.','');const n=Number(s);return s&&Number.isFinite(n)?Math.round(n*100):null;}
export function extractInvoice(text){const amount='([0-9]{1,3}(?:[. \\u00a0][0-9]{3})*(?:,[0-9]{2})|[0-9]+[,.][0-9]{2})';const find=labels=>{const values=[];for(const label of labels){const re=new RegExp('(?:'+label+')[\\s:€]*(?:EUR[\\s:]*)?'+amount,'giu');for(const m of text.matchAll(re)){const v=parseEuro(m[1]);if(v!==null)values.push(v)}}const u=[...new Set(values)];return u.length===1?u[0]:null};let netCents=find(['Rechnungsbetrag\\s*netto','Gesamt(?:betrag|summe)\\s*netto','Summe\\s*netto','Netto(?:betrag|summe)','Netto\\s*gesamt']);if(netCents===null)netCents=find(['Netto']);let grossCents=find(['Brutto(?:betrag|summe)','Rechnungsbetrag\\s*brutto','Gesamt(?:betrag|summe)\\s*brutto','Gesamtbetrag','Rechnungsbetrag(?!\\s*netto)']);const reverseCharge=/§\s*13\s*b|13\s*b\s*UStG|Steuerschuldnerschaft\s+des\s+Leistungsempfängers/i.test(text);if(reverseCharge){if(grossCents===null)grossCents=netCents;if(netCents===null)netCents=grossCents}const invoiceNumber=text.match(/Rechnungs(?:nummer|[-\s]*nr\.?)[\s:]*([a-z0-9][a-z0-9/_-]{1,50})/i)?.[1]||text.match(/\bRechnung\s*Nr\.?[\s:]*([a-z0-9][a-z0-9/_-]{1,50})/i)?.[1]||'';return{netCents,grossCents,invoiceNumber,reverseCharge};}
export function invoiceSettlement({amountCents,netCents,retention=false,discountPercent=0}){const amount=amountCents??netCents;if(!Number.isSafeInteger(amount)||amount<0)throw Error('Rechnungsbetrag prüfen.');if(!Number.isFinite(discountPercent)||discountPercent<0||discountPercent>=100)throw Error('Ungültiger Skontosatz.');const retentionCents=retention?Math.round(amount*.05):0,subtotalCents=amount-retentionCents,discountCents=Math.round(subtotalCents*discountPercent/100),paymentCents=subtotalCents-discountCents;return{amountCents:amount,baseCents:amount,retentionCents,subtotalCents,discountBaseCents:subtotalCents,discountCents,paymentCents,calculationVersion:2};}
export function retentionTotals(records,current,releases=[]){const all=[...Object.values(records).filter(r=>r.reviewed&&r.key!==current.key),current];const companyWithheldCents=all.filter(r=>r.companyId===current.companyId).reduce((s,r)=>s+(r.retentionCents||0),0),projectWithheldCents=all.filter(r=>r.companyId===current.companyId&&r.project===current.project).reduce((s,r)=>s+(r.retentionCents||0),0),paid=releases.filter(r=>r.status==='paid'&&r.companyId===current.companyId),companyReleasedCents=paid.reduce((s,r)=>s+r.amountCents,0),projectReleasedCents=paid.filter(r=>r.project===current.project).reduce((s,r)=>s+r.amountCents,0);return{companyCents:companyWithheldCents-companyReleasedCents,projectCents:projectWithheldCents-projectReleasedCents,companyWithheldCents,projectWithheldCents,companyReleasedCents,projectReleasedCents};}
export{findStampArea,stampInvoice}from'./stamp.mjs';

export function invoiceDiscountPercent(enabled,value){
 if(!enabled)return 0;
 const text=String(value??'').trim().replace(',','.');
 if(!/^\d+(?:\.\d{1,2})?$/.test(text))throw Error('Bitte den Rechnungsskonto-Prozentsatz eingeben.');
 const rate=Number(text);if(!Number.isFinite(rate)||rate<=0||rate>=100)throw Error('Rechnungsskonto muss größer als 0 und kleiner als 100 Prozent sein.');return rate;
}
